@import url('https://fonts.googleapis.com/css2?family=Big+Shoulders:wght@400;500;600;700&family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap');

/* San Antonio Spurs DNA — black and silver, fundamentals only */
.theme-san-antonio-spurs {
  --bg: oklch(0.165 0.004 285.9);
  --surface: oklch(0.205 0.004 286.0);
  --surface-2: oklch(0.249 0.006 286.0);
  --fg: oklch(1.000 0 0);
  --fg-muted: oklch(0.688 0.009 286.2);
  --accent: oklch(0.846 0.014 233.8);
  --accent-fg: oklch(0.165 0.004 285.9);
  --accent-2: oklch(1.000 0 0);
  --line: oklch(1 0 0 / 14%);
  --success: oklch(0.615 0.143 147.4);
  --warning: oklch(0.788 0.151 74.9);
  --danger: oklch(0.615 0.190 27.8);
  --radius: 0.375rem;
  --radius-sm: 0.25rem;
  --radius-lg: 0.5rem;
  --radius-pill: 9999px;
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "Big Shoulders", sans-serif;
  --font-body: "Inter", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: 0.01em;
  --label-transform: uppercase;
  --label-tracking: 0.1em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-san-antonio-spurs h1,
.theme-san-antonio-spurs h2,
.theme-san-antonio-spurs h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-san-antonio-spurs { --font-ui: var(--font-display); }
.theme-san-antonio-spurs h1, .theme-san-antonio-spurs h2 { text-transform: uppercase; font-weight: 800; }
.theme-san-antonio-spurs button { text-transform: uppercase; letter-spacing: 0.08em; font-weight: 700; }

.theme-san-antonio-spurs h1 { color: var(--accent); }
.theme-san-antonio-spurs h2 { color: oklch(0.75 0.005 260); }
.theme-san-antonio-spurs button:hover { background: #ffffff; color: #000000; }

/* depth — fundamentals: hairlines, square corners, no glow, nothing wasted */
.theme-san-antonio-spurs ::selection { background: var(--accent); color: oklch(0.10 0.003 286); }
.theme-san-antonio-spurs a { color: #ffffff; text-decoration-color: var(--accent); text-underline-offset: 3px; }
.theme-san-antonio-spurs a:hover { background: #ffffff; color: #000000; text-decoration: none; }
.theme-san-antonio-spurs thead th { font-family: var(--font-display); text-transform: uppercase; letter-spacing: 0.14em; font-size: 0.78em; font-weight: 600; color: var(--fg-muted); background: transparent; border-top: 1px solid var(--line); border-bottom: 1px solid var(--accent); }
.theme-san-antonio-spurs td { border-bottom: 1px solid oklch(1 0 0 / 8%); }
.theme-san-antonio-spurs tbody tr:hover { background: oklch(1 0 0 / 4%); }
.theme-san-antonio-spurs input, .theme-san-antonio-spurs select, .theme-san-antonio-spurs textarea { background: oklch(0.14 0.003 286); border: 1px solid var(--line); border-radius: 0; caret-color: var(--accent); }
.theme-san-antonio-spurs input:focus-visible, .theme-san-antonio-spurs select:focus-visible, .theme-san-antonio-spurs textarea:focus-visible { outline: 1px solid var(--accent); outline-offset: 0; border-color: var(--accent); box-shadow: none; }
.theme-san-antonio-spurs kbd { font-family: var(--font-mono); background: oklch(0.12 0.003 286); color: var(--accent); border: 1px solid var(--accent); border-radius: 0; padding: 0.1em 0.45em; }
.theme-san-antonio-spurs ::-webkit-scrollbar { width: 8px; height: 8px; }
.theme-san-antonio-spurs ::-webkit-scrollbar-track { background: oklch(0.13 0.003 286); }
.theme-san-antonio-spurs ::-webkit-scrollbar-thumb { background: oklch(0.55 0.010 234); border-radius: 0; }
.theme-san-antonio-spurs ::-webkit-scrollbar-thumb:hover { background: var(--accent); }
.theme-san-antonio-spurs .label-caps { color: var(--accent); letter-spacing: 0.16em; font-weight: 600; }
/* physical: drilled discipline — square featured borders, quiet 1px silver, zero glow */
.theme-san-antonio-spurs .themed-border { border-radius: 0; border-color: var(--accent); box-shadow: none; }
.theme-san-antonio-spurs button { border-radius: 0; }
.theme-san-antonio-spurs button:active { transform: none; background: var(--accent); color: oklch(0.10 0.003 286); }

/* alt mode: away kit (2026-27 real kit / NBA Association Edition) */
.theme-san-antonio-spurs.alt-mode {
  --bg: oklch(0.985 0 0);
  --surface: oklch(1.000 0 0);
  --surface-2: oklch(0.953 0.003 286.3);
  --fg: oklch(0.206 0.006 285.9);
  --fg-muted: oklch(0.478 0.016 285.8);
  --accent: oklch(0.000 0 0);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.642 0.005 236.5);
  --line: oklch(0.914 0.005 286.3);
  --shadow-1: 0 1px 2px oklch(0 0 0 / 8%);
  --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 15%);
  --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 20%);
  background-image: none;
}
.theme-san-antonio-spurs.alt-mode h1 { background: none; -webkit-background-clip: initial; background-clip: initial; color: #000000; -webkit-text-stroke: 0; }
.theme-san-antonio-spurs.alt-mode h2 { color: oklch(0.30 0.006 286); }
.theme-san-antonio-spurs.alt-mode a { color: #000000; text-decoration-color: oklch(0.642 0.005 236.5); }
.theme-san-antonio-spurs.alt-mode a:hover { background: #000000; color: #ffffff; }
.theme-san-antonio-spurs.alt-mode button:hover { background: #000000; color: #ffffff; }
.theme-san-antonio-spurs.alt-mode button:active { background: #000000; color: #ffffff; }
.theme-san-antonio-spurs.alt-mode thead th { border-bottom-color: #000000; }
.theme-san-antonio-spurs.alt-mode td { border-bottom-color: oklch(0 0 0 / 10%); }
.theme-san-antonio-spurs.alt-mode tbody tr:hover { background: oklch(0 0 0 / 4%); }
.theme-san-antonio-spurs.alt-mode input, .theme-san-antonio-spurs.alt-mode select, .theme-san-antonio-spurs.alt-mode textarea { background: oklch(1 0 0); }
.theme-san-antonio-spurs.alt-mode kbd { background: oklch(1 0 0); color: #000000; border-color: #000000; }
.theme-san-antonio-spurs.alt-mode ::-webkit-scrollbar-track { background: oklch(0.95 0.003 286); }
.theme-san-antonio-spurs.alt-mode ::-webkit-scrollbar-thumb { background: oklch(0.60 0.008 236); }
.theme-san-antonio-spurs.alt-mode ::selection { background: #000000; color: #ffffff; }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-app, var(--font-display));
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }

/* OPT-IN HARD MODE — add "sf-enforce" beside the theme class when the host app
   bakes font/shadow/radius literals into its compiled utilities (a var bridge
   cannot beat a literal). Targeted !important, fonts and surfaces only. */
[class*="theme-"].sf-enforce { font-family: var(--font-body) !important; }
[class*="theme-"].sf-enforce :is(h1, h2, h3, h4, [class*="font-heading"]) {
  font-family: var(--font-app, var(--font-display)) !important;
  letter-spacing: var(--tracking-display) !important;
}
/* Data stays data: metrics/KPIs keep the body face with aligned lining figures.
   The display face is for headlines ONLY — never on numbers. Opt specific
   elements INTO the display face with data-sf="display". */
[class*="theme-"] :is([class*="text-2xl"], [class*="text-3xl"], [class*="text-4xl"], [class*="text-5xl"]) {
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce [data-sf="display"] {
  font-family: var(--font-display) !important;
  letter-spacing: var(--tracking-display) !important;
}
[class*="theme-"] :is(.sf-num, [data-sf="num"]) {
  font-family: var(--font-body) !important;
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce :is(button, [role="button"]) { font-family: var(--font-ui, var(--font-body)) !important; }
[class*="theme-"].sf-enforce :is(code, pre, kbd) { font-family: var(--font-mono) !important; }
[class*="theme-"].sf-enforce :is(.bg-card, [class*="card"]) {
  box-shadow: var(--shadow-2) !important;
  border-radius: var(--radius-lg) !important;
  border: var(--border-width) solid var(--line) !important;
}
[class*="theme-"].sf-enforce :is([class*="shadow-sm"], [class*="shadow-md"]) { box-shadow: var(--shadow-1) !important; }
[class*="theme-"].sf-enforce :is([class*="shadow-lg"], [class*="shadow-xl"]) { box-shadow: var(--shadow-3) !important; }
